*/

let BG;
let NUM_REVOL;
let shapes, startFrame, rotAngle;

function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S);
	frameRate(60);
  describe("Radial Spiral of Circles");
	BG_C = color("rgb(212,212,212)");
	FILL_C = color("rgb(190,203,208)")
	fill(FILL_C);
	strokeWeight(2);
	colorMode(HSB);

	startFrame = frameCount;
	rotAngle = random(TWO_PI);
	shapes = makeSpirals();
}

function mouseClicked() {
	if (mouseButton === LEFT) {
		setup();
	}
}

function draw() {
	background(BG_C);
	drawSpirals(shapes, max(0, shapes.length-(frameCount-startFrame)));
}

function makeSpirals() {
	colorMode(HSB)
	const hue1 = random(360);
	const hue2 = hue1 + random(60, 180) * (random() < 0.5 ? 1 : -1);
	const COL1 = color(hue1, 65, 15)
	const COL2 = color(hue2, 45, 15)

  translate(width / 2, height / 2);

  NUM_REVOL = random(0.7, 6);
  let spiralRadMax = width * 0.4; // outer spiral radius
  let spiralRadMin = width * 0.1; // outer spiral radius
  let innerRadMax = (spiralRadMax / 2) / NUM_REVOL;
  let innerRad = innerRadMax;
	let arr = [];
  for (let a = NUM_REVOL * TWO_PI; a >= 0; a -= 0.025) {
		const t = a / (NUM_REVOL * TWO_PI);
    const r = lerp(spiralRadMin, spiralRadMax, t);
    const x = cos(a) * r;
    const y = sin(a) * r;
    if (random() < 0.2) innerRad = noise(x, y) * innerRadMax;
		clr = lerpColor(COL1, COL2, t)
		arr.push({x, y, d: innerRad*2.5, clr});
  }
	return arr;
}

function drawSpirals(arr, start) {
	translate(width / 2, height / 2);
	rotate(rotAngle);

	for (let i = start; i < arr.length; i++) {
		const c = arr[i];
		const f = map(i, 0, arr.length, 0.15, 1);

		fill(lerpColor(BG_C, FILL_C, f))
		let b_clr = c.clr;
		b_clr.setAlpha(f)
		stroke(b_clr)

		strokeWeight(f * 2);
		circle(c.x, c.y, c.d);
	}
}
